/**
 * Copies the art bundle to where the client is served from: `bun run art`.
 *
 * The bundle is generated by the welcome authoring package (`grove/bundle.py` in sequoia-backend's
 * `assets/welcome/authoring`) and is not committed anywhere. It comes from `$GROVE_ART`, by default
 * `../../../sequoia-backend/assets/grove` from `apps/grove` (a checkout beside this one), and goes
 * to `public/grove-art/` (the dev server's static files) and, when there is a build, to
 * `dist/grove-art/`. `bun run build` calls this with `--build`, which copies `public/grove-art/`
 * into the build without needing the source.
 */

import { cp, rm, stat } from "node:fs/promises";
import { resolve } from "node:path";

const app = resolve(import.meta.dir, "..");
const PUBLIC = resolve(app, "public/grove-art");
const DIST = resolve(app, "dist/grove-art");

const exists = async (path: string): Promise<boolean> => {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
};

async function copy(from: string, to: string): Promise<void> {
  await rm(to, { recursive: true, force: true });
  await cp(from, to, { recursive: true });
  console.log(`art: ${from} -> ${to}`);
}

if (process.argv.includes("--build")) {
  if (await exists(resolve(PUBLIC, "manifest.json"))) await copy(PUBLIC, DIST);
  else console.warn("art: no bundle in public/grove-art; run `bun run art` to add one to the build");
} else {
  const source = process.env["GROVE_ART"]
    ? resolve(process.env["GROVE_ART"])
    : resolve(app, "../../../sequoia-backend/assets/grove");
  if (!(await exists(resolve(source, "manifest.json")))) {
    console.error(`art: no bundle at ${source} (set GROVE_ART to the folder holding manifest.json)`);
    process.exit(1);
  }
  await copy(source, PUBLIC);
  if (await exists(resolve(app, "dist"))) await copy(source, DIST);
}
